import numpy as np

def fit_bounds(actions, lo_pct=1.0, hi_pct=99.0):
    """actions: (n, d). Return (low, high), each of shape (d,)."""
    return actions.min(axis=0), actions.max(axis=0)

def tokenize(actions, low, high, n_bins=256):
    """(n, d) actions -> (n, d) integer tokens in 0 .. n_bins-1."""
    return np.zeros(actions.shape, dtype=int)

def detokenize(tokens, low, high, n_bins=256):
    """(n, d) tokens -> (n, d) actions at the centres of their bins."""
    return np.zeros(tokens.shape)

exercises.reference:
import numpy as np

def fit_bounds(actions, lo_pct=1.0, hi_pct=99.0):
    return np.percentile(actions, lo_pct, axis=0), np.percentile(actions, hi_pct, axis=0)

def tokenize(actions, low, high, n_bins=256):
    a = np.clip(actions, low, high)
    idx = np.floor((a - low) / (high - low) * n_bins).astype(int)
    return np.minimum(idx, n_bins - 1)

def detokenize(tokens, low, high, n_bins=256):
    return low + (tokens + 0.5) * (high - low) / n_bins

exercises.solution:
Bounds come from per-column percentiles; everything else broadcasts over the `(n, d)` array.

```python
import numpy as np

def fit_bounds(actions, lo_pct=1.0, hi_pct=99.0):
    return np.percentile(actions, lo_pct, axis=0), np.percentile(actions, hi_pct, axis=0)

def tokenize(actions, low, high, n_bins=256):
    a = np.clip(actions, low, high)
    idx = np.floor((a - low) / (high - low) * n_bins).astype(int)
    return np.minimum(idx, n_bins - 1)

def detokenize(tokens, low, high, n_bins=256):
    return low + (tokens + 0.5) * (high - low) / n_bins
```

The `np.minimum` matters: without it a value exactly at `high` would become token `n_bins`, which does not exist. Using percentiles instead of the minimum and maximum keeps a few outliers from widening every bin; 2% of values are clipped, which is the price. In a real VLA these integers are then mapped onto 256 rarely used entries of the language model's vocabulary.
